/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `trg_employee_no_self_manager` BEFORE INSERT ON `employees` FOR EACH ROW IF NEW.manager_id IS NOT NULL AND NEW.manager_id = NEW.id THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Employee cannot be their own manager';
  END IF */;;
